import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { logos4Schema, type Logos4 } from "./logos4.js";

/** The embed settings of the event and the videos generated by streaming to this event. */
export type Embed7 = {
  /** Whether playback starts automatically on load. */
  autoplay?: boolean;
  /** The hexadecimal color code for the main color of the embed player. */
  color?: string;
  logos?: Logos4;
  /**
   * Whether the playlist should start from the beginning again after reaching the end of the last
   * video.
   */
  loop?: boolean;
  /** Whether to show the playlist controls on the embed player. */
  playlist?: boolean;
  /** Whether to show the event schedule on the embed player. */
  schedule?: boolean;
  /** Whether to show the latest archived video in the embed player when off-air. */
  showLatestArchivedClip?: boolean;
  /** Whether the embed player should use (`true`) or ignore (`false`) the **embed.color** value. */
  useColor?: boolean;
};

export const embed7Schema: Schema<Embed7> = s.object<Embed7>({
  autoplay: s.optional(s.boolean()),
  color: s.optional(s.string()),
  logos: s.optional(s.lazy(() => logos4Schema)),
  loop: s.optional(s.boolean()),
  playlist: s.optional(s.boolean()),
  schedule: s.optional(s.boolean()),
  showLatestArchivedClip: s.optional(s.boolean()),
  useColor: s.optional(s.boolean()),
  _keysMap: {
    showLatestArchivedClip: "show_latest_archived_clip",
    useColor: "use_color",
  },
});
